const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Approximate location of the North Crimean Canal in Kherson region, Ukraine
  // This point is chosen to be representative of agricultural land along the canal.
  const canalPoint = ee.Geometry.Point(33.56, 46.29); // Example point near the canal
  const geometry = canalPoint.buffer(5000); // 5km buffer to cover surrounding cropland

  const start_date_2023 = '2023-06-03';
  const end_date_2023 = '2023-07-19';
  const start_date_2022 = '2022-06-03';
  const end_date_2022 = '2022-07-19';

  // 2. Data Acquisition & Cloud Masking
  // Function to mask clouds from Sentinel-2 surface reflectance data.
  function maskS2clouds(image) {
    const QA60 = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = QA60.bitwiseAnd(cloudBitMask).eq(0)
      .and(QA60.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale to 0-1 reflectance
  }

  // Function to calculate NDVI
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // Get Sentinel-2 collections
  let collection_2023 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(start_date_2023, end_date_2023)
    .filterBounds(geometry)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 60)) // Filter for less cloudy images
    .map(maskS2clouds)
    .map(addNDVI);

  let collection_2022 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(start_date_2022, end_date_2022)
    .filterBounds(geometry)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 60)) // Filter for less cloudy images
    .map(maskS2clouds)
    .map(addNDVI);

  // Check if collections are empty
  const size_2023 = await collection_2023.size().getInfo();
  const size_2022 = await collection_2022.size().getInfo();

  if (size_2023 === 0 || size_2022 === 0) {
    console.log(`2023 Images: ${size_2023}`);
    console.log(`2022 Images: ${size_2022}`);
    console.log("Empty Collection (No images found for one or both periods after initial filter).");
    console.log("C1");
    return;
  }

  // Compute the mean NDVI for each period
  const mean_ndvi_2023_img = collection_2023.select('NDVI').mean();
  const mean_ndvi_2022_img = collection_2022.select('NDVI').mean();

  // 3. Processing - Calculate pixel count to detect C2
  const scale = 30; // Sentinel-2 resolution is 10m for visible/NIR, but using 30m for aggregation to reduce memory.
  const reducer = ee.Reducer.mean().setOutputs(['NDVI']);

  const stats_2023 = await mean_ndvi_2023_img.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const stats_2022 = await mean_ndvi_2022_img.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const pixel_count_2023 = stats_2023 ? stats_2023.NDVI : 0;
  const pixel_count_2022 = stats_2022 ? stats_2022.NDVI : 0;

  if (pixel_count_2023 === 0 || pixel_count_2022 === 0) {
    console.log(`2023 Images: ${size_2023} (Val Pixels: ${pixel_count_2023})`);
    console.log(`2022 Images: ${size_2022} (Val Pixels: ${pixel_count_2022})`);
    console.log("No Valid Pixels (after cloud masking/processing, 0 pixels remain).");
    console.log("C2");
    return;
  }

  // 4. Calculation
  const mean_ndvi_2023_val = await mean_ndvi_2023_img.reduceRegion({
    reducer: reducer,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const mean_ndvi_2022_val = await mean_ndvi_2022_img.reduceRegion({
    reducer: reducer,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // 5. Validation & Final Answer
  if (mean_ndvi_2023_val === null || mean_ndvi_2022_val === null) {
    console.log("Calculation Failure (NDVI result is None).");
    console.log("C3");
    return;
  }

  const ndvi_diff = mean_ndvi_2023_val - mean_ndvi_2022_val;
  // A negative difference means 2023 NDVI is lower, indicating "browner" conditions.
  // Set a threshold for "significantly browner", e.g., a drop of 0.05 in NDVI.
  const browner_threshold = -0.05;

  console.log(`2023 Images: ${size_2023} (Val Pixels: ${pixel_count_2023}, Mean NDVI: ${mean_ndvi_2023_val.toFixed(3)})`);
  console.log(`2022 Images: ${size_2022} (Val Pixels: ${pixel_count_2022}, Mean NDVI: ${mean_ndvi_2022_val.toFixed(3)})`);
  console.log(`NDVI Difference (2023 - 2022): ${ndvi_diff.toFixed(3)}`);

  if (ndvi_diff < browner_threshold) {
    console.log("A"); // 2023 NDVI is significantly lower than 2022
  } else {
    console.log("B"); // Not significantly browner
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
